/** Discord caps autocomplete choice name and value at 100 characters. */
export const SEALED_PRODUCT_NAME_MAX = 100;

/**
 * Split a digest message into chunks that fit within the Discord message limit.
 * Blocks are separated by blank lines and are never split. Lines within a block
 * that exceed the limit are truncated to fit.
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  const blocks = text.split(/\n\s*\n/);
  const messages: string[] = [];
  let current = '';

  const pushBlock = (block: string): void => {
    while (block.length > 0) {
      if (current.length + block.length + 1 <= limit) {
        current += (current.length > 0 ? '\n' : '') + block;
      } else {
        if (current.length > 0) {
          messages.push(current);
        }
        current = block.slice(0, limit);
        block = block.slice(limit).trim();
      }
    }
    if (current.length > 0) {
      messages.push(current);
    }
    current = '';
  };

  for (const block of blocks) {
    if (block.trim().length === 0) continue;
    if (current.length === 0) {
      pushBlock(block);
    } else if (current.length + block.length + 1 <= limit) {
      current += '\n\n' + block;
    } else {
      pushBlock(block);
    }
  }

  if (current.length > 0) {
    messages.push(current);
  }

  return messages;
}

