  messages: string[],
  sendFn: (message: string) => Promise<boolean>,
): Promise<boolean> {
  for (const msg of messages) {
    try {
      await retryWithBackoff(
        () => (sendFn as (content: string) => Promise<boolean>)(msg),
        { attempts: 3, baseDelayMs: 1000, maxDelayMs: 8000 },
      );
    } catch {
      return false;
    }
  }
  return true;
