import type { Client } from 'discord.js';
import { describe, expect, it, vi } from 'vitest';
import { getDb } from '../../src/db/index.js';
import {
  listings,
  servers,
  type ListingRow,
  type NewListingRow,
  type NewServerRow,
} from '../../src/db/schema.js';
import { formatDigest, runDigest, splitDigestMessage } from '../../src/services/digest.js';
import { getServerConfig } from '../../src/services/digest-state.js';
import { DIGEST_SECTION_CAP, DISCORD_MESSAGE_MAX_LENGTH } from '../../src/utils/constants.js';
import { setupTestDb } from '../helpers/db.js';

setupTestDb();

function listing(overrides: Partial<ListingRow> = {}): ListingRow {
  return {
    id: 1,
    serverId: '200',
    userId: 'u1',
    username: 'alice',
    intent: 'have',
    accepts: 'cash',
    game: 'mtg',
    cardName: 'Black Lotus',
    cardNameNormalized: 'black lotus',
    cardSet: 'LEA',
    cardImageUrl: null,
    finish: null,
    variant: null,
    collectorNumber: null,
    manapoolUrl: null,
    condition: 'nm',
    priceCents: 4500000,
    quantity: 1,
    notes: null,
    status: 'active',
    expiresAt: 2,
    createdAt: 1,
    updatedAt: 1,
    ...overrides,
  };
}

describe('formatDigest', () => {
  it('groups listings by intent with headings', () => {
    const text = formatDigest([
      listing({ id: 1, intent: 'have', cardName: 'Black Lotus', username: 'alice' }),
      listing({ id: 2, intent: 'want', cardName: 'Force of Will', priceCents: null }),
      listing({ id: 3, intent: 'have', accepts: 'trade', cardName: 'Tarmogoyf', condition: 'lp' }),
    ]);
    expect(text).toContain('NEW HAVES (2)');
    expect(text).toContain('NEW WANTS (1)');
    expect(text).toContain('- Black Lotus (LEA) — NM — $45,000.00 — @alice');
  });

  it('omits empty sections', () => {
    const text = formatDigest([listing({ id: 1, intent: 'have' })]);
    expect(text).not.toContain('NEW WANTS');
  });

  it('appends a Manapool link when available', () => {
    const text = formatDigest([
      listing({
        id: 1,
        intent: 'have',
        manapoolUrl: 'https://manapool.com/card/lea/232/black-lotus',
      }),
    ]);
    expect(text).toContain('[View on Manapool](https://manapool.com/card/lea/232/black-lotus)');
  });

  it('caps each section and notes overflow', () => {
    const rows = Array.from({ length: DIGEST_SECTION_CAP + 5 }, (_, i) =>
      listing({ id: i + 1, intent: 'have', cardName: `Card ${i + 1}` }),
    );
    const text = formatDigest(rows);
    expect(text).toContain('NEW HAVES (30)');
    expect(text).toContain('+5 more');
    expect(text).toContain('- Card 1 (LEA)');
    expect(text).not.toContain('- Card 26 (LEA)');
  });
});

const serverRow: NewServerRow = {
  id: '500',
  digestMode: 'channel',
  digestCron: '0 9 * * *',
  digestTimezone: 'UTC',
  enabledGames: '["mtg"]',
  adminChannelId: 'channel-1',
  digestDmUserId: null,
  lastDigestAt: 0,
  removedAt: null,
  createdAt: 1,
  updatedAt: 1,
};

function addListing(): void {
  getDb()
    .insert(listings)
    .values({
      serverId: '500',
      userId: 'u1',
      username: 'alice',
      intent: 'have',
      accepts: 'cash',
      game: 'mtg',
      cardName: 'Black Lotus',
      cardNameNormalized: 'black lotus',
      cardSet: null,
      cardImageUrl: null,
      finish: null,
      variant: null,
      collectorNumber: null,
      manapoolUrl: null,
      condition: 'nm',
      priceCents: 100,
      quantity: 1,
      notes: null,
      status: 'active',
      expiresAt: Date.now() + 30 * 24 * 3600 * 1000,
      createdAt: Date.now(),
      updatedAt: Date.now(),
    } satisfies NewListingRow)
    .run();
}

function fakeClientWithChannelSend(send: (message: string) => Promise<unknown>): Client {
  return {
    channels: {
      fetch: vi.fn().mockResolvedValue({
        isTextBased: () => true,
        isSendable: () => true,
        send,
      }),
    },
  } as unknown as Client;
}

describe('runDigest delivery retry', () => {
  it('succeeds and advances the watermark when a transient send failure is retried', async () => {
    getDb().insert(servers).values(serverRow).run();
    addListing();
    const send = vi
      .fn()
      .mockRejectedValueOnce(new Error('transient 503'))
      .mockResolvedValueOnce(undefined);
    const client = fakeClientWithChannelSend(send);

    const result = await runDigest(client, getServerConfig('500')!, 'scheduled');

    expect(result.sent).toBe(true);
    expect(result.channelOk).toBe(true);
    expect(send).toHaveBeenCalledTimes(2);
    expect(getServerConfig('500')!.lastDigestAt).toBeGreaterThan(0);
  });

  it('suppresses mention parsing so a display name like "everyone" cannot mass-ping the channel', async () => {
    getDb().insert(servers).values(serverRow).run();
    addListing();
    const send = vi.fn().mockResolvedValue(undefined);
    const client = fakeClientWithChannelSend(send);

    await runDigest(client, getServerConfig('500')!, 'scheduled');

    expect(send).toHaveBeenCalledWith(expect.objectContaining({ allowedMentions: { parse: [] } }));
  });

  it('gives up after repeated failures and leaves the watermark unchanged', async () => {
    getDb().insert(servers).values(serverRow).run();
    addListing();
    const send = vi.fn().mockRejectedValue(new Error('persistent failure'));
    const client = fakeClientWithChannelSend(send);

    const result = await runDigest(client, getServerConfig('500')!, 'scheduled');

    expect(result.sent).toBe(false);
    expect(result.channelOk).toBe(false);
    expect(getServerConfig('500')!.lastDigestAt).toBe(0);
    expect(send).toHaveBeenCalledTimes(3);
  }, 10_000);
});

describe('splitDigestMessage', () => {
  it('returns text unchanged when it fits within the limit', () => {
    const text = 'This is a short message.';
    const result = splitDigestMessage(text);
    expect(result).toEqual([text]);
  });

  it('splits text into multiple messages when it exceeds the limit, preserving order', () => {
    const line = 'x'.repeat(250);
    const text = `${line}\n${line}\n${line}\n`;
    const result = splitDigestMessage(text, 100);
    expect(result).toHaveLength(10);
    result.forEach((m, i) => expect(m.length).toBeLessThanOrEqual(100));
    expect([...text]).toEqual([...result.join('')]);
  });

  it('does not split a block that fits within the limit', () => {
    const block1 = 'a'.repeat(79);
    const block2 = 'b'.repeat(79);
    const text = `${block1}\n\n${block2}`;
    const result = splitDigestMessage(text, 100);
    expect(result).toHaveLength(2);
    expect(result[0]).toBe(block1);
    expect(result[1]).toBe(block2);
  });

  it('cuts lines that exceed the limit', () => {
    const longLine = 'x'.repeat(250);
    const text = longLine;
    const result = splitDigestMessage(text, 100);
    expect(result[0]).toHaveLength(100);
    expect(result[1]).toHaveLength(100);
    expect(result[2]).toHaveLength(50);
  });

  it('ensures no message exceeds the limit', () => {
    const text = 'x'.repeat(2000);
    const result = splitDigestMessage(text, 2000);
    expect(result[0]).toHaveLength(2000);
    expect(result).toHaveLength(1);
  });

  it('handles empty input', () => {
    expect(splitDigestMessage('')).toEqual([]);
  });

  it('preserves all content when splitting across blocks', () => {
    const block1 = 'a'.repeat(150);
    const block2 = 'b'.repeat(150);
    const text = `${block1}\n\n${block2}`;
    const result = splitDigestMessage(text, 200);
    expect([...text]).toEqual([...result.join('')]);
  });
});

describe('runDigest on busy days', () => {
  function addBusyDay(): void {
    for (let i = 0; i < 20; i++) {
      getDb()
        .insert(listings)
        .values({
          serverId: '500',
          userId: `u${i + 1}`,
          username: `user${i + 1}`,
          intent: i % 2 === 0 ? 'have' : 'want',
          accepts: i % 2 === 0 ? 'cash' : 'trade',
          game: 'mtg',
          cardName: `Card ${i + 1}`,
          cardNameNormalized: `card ${i + 1}`,
          cardSet: 'M19',
          cardImageUrl: `https://picsum.photos/seed/${i}`,
          finish: i % 3 === 0 ? 'foil' : null,
          variant: null,
          collectorNumber: null,
          manapoolUrl: `https://manapool.com/card/m19/${i + 1}/card-${i + 1}`,
          condition: i % 4 === 0 ? 'dmg' : 'nm',
          priceCents: i * 100,
          quantity: 1,
          notes: null,
          status: 'active',
          expiresAt: Date.now() + 30 * 24 * 3600 * 1000,
          createdAt: Date.now() - i * 1000,
          updatedAt: Date.now(),
        } satisfies NewListingRow)
        .run();
    }
  }

  it('sends multiple chunks and advances the watermark when all succeed', async () => {
    getDb().insert(servers).values(serverRow).run();
    addBusyDay();

    const totalChunks = 10;
    const send = vi.fn().mockImplementation(async (msg: string) => {
      if (msg.length > 250) {
        throw new Error('chunk error');
      }
      return Promise.resolve();
    });
    const client = fakeClientWithChannelSend(send);

    const result = await runDigest(client, getServerConfig('500')!, 'scheduled');

    expect(result.sent).toBe(true);
    expect(result.channelOk).toBe(true);
    expect(send).toHaveBeenCalledTimes(totalChunks);
    expect(getServerConfig('500')!.lastDigestAt).toBeGreaterThan(0);
  });

  it('leaves watermark unchanged when a chunk send keeps failing', async () => {
    getDb().insert(servers).values(serverRow).run();
    addBusyDay();

    const send = vi.fn().mockRejectedValueOnce(new Error('transient failure'));
    const client = fakeClientWithChannelSend(send);

    const result = await runDigest(client, getServerConfig('500')!, 'scheduled');

    expect(result.sent).toBe(false);
    expect(result.channelOk).toBe(false);
    expect(getServerConfig('500')!.lastDigestAt).toBe(0);
    expect(send).toHaveBeenCalledTimes(4);
  }, 10_000);
});

