async function deliverMultipleAsync<T>(
  messages: string[],
  sendFn: (message: string) => Promise<boolean>,
): Promise<boolean> {
  for (const msg of messages) {
    try {
      await retryWithBackoff(
        () => (sendFn as (content: string) => Promise<boolean>)(msg),
        { attempts: 3, baseDelayMs: 1000, maxDelayMs: 8000 },
      );
    } catch {
      return false;
    }
  }
  return true;
}

async function deliverToChannel(
  client: Client,
  server: ServerRow,
  message: string,
): Promise<boolean> {
  if (!server.adminChannelId) {
    return false;
  }
  try {
    const channel = (await client.channels.fetch(server.adminChannelId)) as TextChannel | null;
    if (!channel || !channel.isTextBased() || !channel.isSendable()) {
      return false;
    }
    await retryWithBackoff(
      () => channel.send({ content: message, allowedMentions: { parse: [] } }),
      {
        attempts: 3,
        baseDelayMs: 1000,
        maxDelayMs: 8000,
      },
    );
    return true;
  } catch {
    return false;
  }
}

async function deliverToDm(client: Client, server: ServerRow, message: string): Promise<boolean> {
  if (!server.digestDmUserId) {
    return false;
  }
  try {
    const user = (await client.users.fetch(server.digestDmUserId)) as User | null;
    if (!user) {
      return false;
    }
    await retryWithBackoff(() => user.send({ content: message, allowedMentions: { parse: [] } }), {
      attempts: 3,
      baseDelayMs: 1000,
      maxDelayMs: 8000,
    });
    return true;
  } catch {
    return false;
  }
}

