/**
 * Split a digest message into chunks that fit within the Discord message limit.
 * Blocks are separated by blank lines and are never split. Lines within a block
 * that exceed the limit are truncated to fit.
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  const blocks = text.split(/\n\n+/);
  const messages: string[] = [];
  let current = '';

  const flush = (): void => {
    if (current.length > 0) {
      messages.push(current);
    }
    current = '';
  };

  for (const block of blocks) {
    if (block === '') continue;
    if (current.trim().length === 0) {
      current = block;
    } else if (current.length + block.length + 1 <= limit) {
      current += '\n' + block;
    } else {
      flush();
      const afterSplit = splitOneBlock(block, limit);
      if (afterSplit.length === 1) {
        current = afterSplit[0];
      } else if (afterSplit.length === 0) {
        // Entire block didn't fit; discard
      } else {
        for (const chunk of afterSplit) {
          messages.push(chunk);
        }
      }
    }
  }

  flush();

  return messages;
}

/**
 * Split a single block (separated by blank lines) into chunks that fit in limit.
 * Truncates lines that exceed the limit.
 */
function splitOneBlock(block: string, limit: number): string[] {
  const result: string[] = [];
  const lines = block.split('\n');
  let current = '';

  for (const line of lines) {
    // Check if adding this line exceeds limit
    if (current.length > 0) {
      const withNewline = current.length + 1 + line.length;
    }
    current += line + '\n';
  }

  if (block.length > limit) {
    result.push(block.slice(0, limit));
    let remaining = block.slice(limit);
    while (remaining.length > 0) {
      const chunk = remaining.slice(0, limit);
      result.push(chunk);
      remaining = remaining.slice(limit);
    }
  }

  return result;
}

