}

/**
 * Split a block (content between blank lines) into multiple messages.
 * Returns an array of message chunks. Each chunk is <= limit chars.
 */
function blockSplitInChunks(block: string, limit: number): string[] {
  const chunks: string[] = [];
  const lines = block.split('\n');

  let i = 0;
  while (i < lines.length) {
    const line = lines[i];

    // Start collecting lines for this chunk
    let currentChunk = '';
    const lineParts: string[] = [];
    let j = i;

    // Collect lines while they fit
    while (j < lines.length) {
      const otherLine = lines[j];
      const addNewline = j > i ? '\n' : '';
      const proposedLength = currentChunk.length + addNewline.length + otherLine.length;

      if (proposedLength <= limit) {
        if (j > i || currentChunk.length > 0) {
          currentChunk += addNewline;
        }
        currentChunk += otherLine;
        j++;
      } else {
        break;
      }
    }

    if (currentChunk.length > 0) {
      chunks.push(currentChunk);
    }

    i = j;
  }

  return chunks;
}

