/**
 * Split a digest message into chunks that fit within the Discord message limit.
 * Blocks are separated by blank lines and are never split. Lines within a block
 * that exceed the limit are truncated to fit.
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  const blocks = text.split(/\n\n+/);
  const messages: string[] = [];

  for (const block of blocks) {
    if (block.trim().length === 0) continue;

    const chunk = splitBlock(block, limit);
    if (chunk.length > 0) {
      messages.push(chunk);
    }
  }

  return messages;
}

/**
 * Split a single block (between blank lines) into multiple messages.
 * Never splits inside a block; only outputs the block as-is or splits it into chunks.
 */
function splitBlock(block: string, limit: number): string {
  // First, check if block fits entirely
  if (block.length <= limit) {
    return block;
  }

  // Block exceeds limit; need to split into multiple chunks
  const lines = block.split('\n');
  const chunks: string[] = [];
  let current = '';

  const flush = (): void => {
    if (current.length > 0) {
      chunks.push(current);
    }
    current = '';
  };

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const needsNewline = current.length > 0;

    if (current.length + (needsNewline ? 1 : 0) + line.length <= limit) {
      current += (needsNewline ? '\n' : '') + line;
    } else {
      flush();
      if (line.length > 0) {
        let remaining = line;
        while (remaining.length > 0) {
          const chunk = remaining.slice(0, limit);
          chunks.push(chunk);
          remaining = remaining.slice(limit);
        }
      }
    }
  }

  flush();

  return chunks.join('\n\n');
}

