input.newString:
/**
 * Split a digest message into chunks that fit within the Discord message limit.
 * Blocks are separated by blank lines and are never split. Lines within a block
 * that exceed the limit are truncated to fit.
 */
export function splitDigestMessage(text: string, limit = DISCORD_MESSAGE_MAX_LENGTH): string[] {
  const messages: string[] = [];
  const chars = text.split('');

  if (chars.length === 0) return messages;

  let i = 0;
  while (i < chars.length) {
    const chunk: string[] = [];
    let start = i;
    let j = i;

    while (j < chars.length && j - start < limit) {
      const char = chars[j];
      if (char === '\n' || char === '\r') {
        // Only break for blank line (double \n separated by optional whitespace)
        let k = j + 1;
        let blank = false;
        while (k < chars.length && chars[k] === ' ') {
          k++;
        }
        if (k < chars.length && chars[k] === '\n') {
          // Next char is also \n -> blank line
          blank = true;
          break;
        }
        // Not a blank line, include the \n
        break;
      }
      chunk.push(chars[j++]);
    }

    messages.push(chunk.join(''));
    i = j;
  }

  return messages;
}

